package com.beeboee.magnot.region;
import net.minecraft.world.phys.Vec3;import java.util.*;
final class FerrousRegionIndex{private final Map<Long,List<FerrousRegion>> map=new HashMap<>();static FerrousRegionIndex build(List<FerrousRegion> rs){FerrousRegionIndex i=new FerrousRegionIndex();for(FerrousRegion r:rs)i.add(r);return i;}boolean contains(Vec3 p){List<FerrousRegion> rs=map.get(key(sec(p.x),sec(p.y),sec(p.z)));if(rs==null)return false;for(FerrousRegion r:rs)if(r.contains(p))return true;return false;}boolean blocks(Vec3 a,Vec3 b){Set<FerrousRegion> seen=new HashSet<>();for(int x=sec(Math.min(a.x,b.x));x<=sec(Math.max(a.x,b.x));x++)for(int y=sec(Math.min(a.y,b.y));y<=sec(Math.max(a.y,b.y));y++)for(int z=sec(Math.min(a.z,b.z));z<=sec(Math.max(a.z,b.z));z++){List<FerrousRegion> rs=map.get(key(x,y,z));if(rs!=null)for(FerrousRegion r:rs)if(seen.add(r)&&r.intersectsSegment(a,b))return true;}return false;}private void add(FerrousRegion r){for(int x=sec(r.min().getX());x<=sec(r.max().getX());x++)for(int y=sec(r.min().getY());y<=sec(r.max().getY());y++)for(int z=sec(r.min().getZ());z<=sec(r.max().getZ());z++)map.computeIfAbsent(key(x,y,z),q->new ArrayList<>()).add(r);}private static int sec(double v){return Math.floorDiv((int)Math.floor(v),16);}private static long key(int x,int y,int z){return((long)x&0x3FFFFFFL)<<38|((long)z&0x3FFFFFFL)<<12|((long)y&0xFFFL);}}
